#!/usr/bin/env node
/**
 * Plugin that runs as subprocess
 * Reads JSON-RPC from stdin, writes to stdout
 */

import { createInterface } from 'readline';
import { OpenAIProvider } from './actual-plugin.js';

class PluginServer {
  constructor(plugin) {
    this.plugin = plugin;
  }

  async handleRequest(request) {
    const { method, params } = request;

    try {
      let result;

      switch (method) {
        case 'init':
          result = await this.plugin.init(params.model_id, params.config);
          break;

        case 'can_handle':
          result = this.plugin.canHandle(
            params.capability_id,
            params.meta_state
          );
          break;

        case 'to_native_messages':
          result = this.plugin.toNativeMessages(
            params.messages,
            params.meta_state
          );
          break;

        case 'stream_api':
          // Handle streaming
          for await (const chunk of this.plugin.streamApi(
            params.body,
            params.config,
            params.meta_state
          )) {
            console.log(JSON.stringify({
              jsonrpc: '2.0',
              id: request.id,
              result: { chunk, done: false }
            }));
          }

          return {
            jsonrpc: '2.0',
            id: request.id,
            result: { done: true }
          };

        default:
          throw new Error(`Unknown method: ${method}`);
      }

      return {
        jsonrpc: '2.0',
        id: request.id,
        result
      };

    } catch (error) {
      return {
        jsonrpc: '2.0',
        id: request.id,
        error: {
          code: -1,
          message: error.message
        }
      };
    }
  }

  async run() {
